mapper.select:
select *
from system_users
where username = #{username}
  and enterprise_id = #{enterpriseId}
  and delete_flag = 0


where su.delete_flag = 0

    and su.username like concat('%', #{pageReqVO.username}, '%')


    and su.nickname like concat('%', #{pageReqVO.nickName}, '%')


    and su.mobile like concat('%', #{pageReqVO.mobile}, '%')


    and su.status = #{pageReqVO.status.value}


    and su.enterprise_id = #{pageReqVO.enterpriseId}


    and su.dept_id in

        #{deptId}

select su.id, su.username, su.nickname, su.enterprise_id, se.enterprise_name, su.dept_id, sd.name as dept_name, login_ip, login_date from system_users su left join system_enterprise se on se.id = su.enterprise_id left join system_dept sd on sd.id = su.dept_id where su.delete_flag = 0 and su.status = 0 and exists(select so2at.id from system_oauth2_access_token so2at where so2at.delete_flag = 0 and so2at.user_id = su.id and so2at.expires_time > now())
and su.username like concat('%', #{req.username}, '%')
and su.nickname like concat('%', #{req.nickname}, '%')
and su.enterprise_id = #{req.enterpriseId}
and su.dept_id = #{req.deptId}
and su.login_date >= #{req.loginDateStart}
and su.login_date <= #{req.loginDateEnd}
order by su.login_date desc
